<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dokumentcenter – MeldeVerkehr</title>
<style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:1100px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}input,select{padding:9px;border:1px solid #bac5d1;border-radius:8px}button,.button{display:inline-block;padding:8px 12px;border:0;border-radius:8px;background:#172033;color:#fff;text-decoration:none;font-weight:700}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #e5e9ee;text-align:left}.hash{font-family:ui-monospace,monospace;font-size:.75rem;word-break:break-all}.muted{color:#66758a}</style></head><body><main>
<p><a href="/dashboard">Dashboard</a> · <a href="/search">Suche</a></p><h1>Dokumentcenter</h1>
<section class="card"><form method="get" action="/documents"><input name="q" value="<?= $e($query) ?>" placeholder="Titel / Vorgangsnummer"><select name="type"><option value="">Alle Typen</option><?php foreach(['EVIDENCE_PACKAGE','WITNESS_REPORT','DISPATCH_PACKAGE','AUTHORITY_ATTACHMENT','MUNICIPAL_REPORT','EXPORT'] as $t):?><option value="<?= $e($t) ?>" <?= $type===$t?'selected':'' ?>><?= $e($t) ?></option><?php endforeach;?></select><button type="submit">Filtern</button></form></section>
<section class="card"><table><thead><tr><th>Typ</th><th>Dokument</th><th>Version</th><th>Datum</th><th>Integrität</th><th>Aktion</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?= $e($item['type']) ?></td><td><strong><?= $e($item['title']) ?></strong><?php if($item['filename']):?><br><small><?= $e($item['filename']) ?></small><?php endif;?></td><td><?= $e($item['version']??'–') ?></td><td><?= $e($item['created_at']) ?></td><td class="hash"><?= $e($item['sha256']??'–') ?></td><td><?php if($item['open_url']):?><a class="button" href="<?= $e($item['open_url']) ?>">Öffnen</a><?php endif;?> <?php if($item['download_url']):?><a class="button" href="<?= $e($item['download_url']) ?>">Download</a><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php if(!$items):?><p class="muted">Keine Dokumente gefunden.</p><?php endif;?></section>
</main></body></html>